# ---------------- writer / verifier ----------------
def main():
    batches = json.load(open(BATCHES, encoding="utf-8"))
    ids = batches["B16"] + batches["B17"] + batches["B18"]
    assert len(ids) == 60, len(ids)
    assert set(P.keys()) == set(ids), (set(ids) - set(P.keys()), set(P.keys()) - set(ids))
    os.makedirs(OUT, exist_ok=True)
    total = 0
    for cid in ids:
        rec = {"case_id": cid}
        rec.update(P[cid])
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        total += os.path.getsize(path)
    # verify: re-open each file by exact id only
    cm = ru = di = 0
    for cid in ids:
        path = os.path.join(OUT, cid + ".json")
        d = json.load(open(path, encoding="utf-8"))
        assert d["case_id"] == cid
        assert set(d.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, d.keys()
        t = d["trigger"]
        assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])
        if cid.startswith("MH") or cid.startswith("MP"):
            assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, cid
    print(f"cases={len(ids)} written=60 total_bytes={total} changed_main={cm} reserve_used={ru} disputed={di}")

if __name__ == "__main__":
    main()
